{
  "participants": [
    {
      "login": "jeanpablojp",
      "stance": "support",
      "note": "tACK with a suggestion to add an explanatory comment on UniValue error handling"
    },
    {
      "login": "Eunovo",
      "stance": "objection",
      "note": "criticized generating random byte vectors rather than structured valid payloads (ConsumeTransaction/valid JSON); author explained raw bytes intentionally test deserialization of malformed responses"
    }
  ],
  "claims": [
    {
      "id": "rc:4014137549",
      "kind": "approach",
      "harm": "random byte vectors rarely deserialize to a valid CTransaction, missing deeper fuzz coverage",
      "quote": "Use `ConsumeTransaction` in `src/test/fuzz/util.cpp` to create a random tx from a `FuzzedDataProvider` instead of using a random lenght byte vector.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:4028056645"
      ],
      "fix_pushed": false,
      "settled_by_id": "rc:4028056645",
      "settled_by_quote": "We intentionally return arbitrary transaction bytes from the raw server so the client deserialization is exercised with malformed responses. Using `ConsumeTransaction` would only generate valid transactions and duplicate the existing passTransaction coverage."
    },
    {
      "id": "rc:4014184111",
      "kind": "approach",
      "harm": "most generated data will be invalid JSON and repeatedly hit deserialization errors instead of exercising inner logic",
      "quote": "Most of the generated data will be invalid JSON; this means the fuzzer will hit the \"invalid JSON received over IPC\" error most of the time. I think it's much better to construct a valid JSON payload, the same way we construct valid TXs with `ConsumeTransaction`.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:4028056893"
      ],
      "fix_pushed": false,
      "settled_by_id": "rc:4028056893",
      "settled_by_quote": "Invalid json is intentional here because it tests client side rejection of malformed ipc responses. Valid json round trips are covered separately by passUniValue, which parses arbitrary input and proceeds when it is valid."
    }
  ],
  "support": [
    {
      "id": "r:4944146103",
      "verdict": "Tested ACK",
      "reason": "All green, and it matches the follow-up #35118 asked for.",
      "substantive": true
    }
  ],
  "notes": "Eunovo raised objections across review comments suggesting ConsumeTransaction and valid JSON instead of arbitrary byte vectors. enirox001 replied with a rationale (testing malformed deserialization paths that normal serialization bypasses) and added comments in code without pushback from Eunovo."
}
